package com.allinone.supply.service.impl;
import com.allinone.common.exception.ServiceException; import com.allinone.common.utils.SecurityUtils; import com.allinone.common.utils.uuid.IdUtils; import com.allinone.supply.domain.WorkflowConfig; import com.allinone.supply.mapper.WorkflowConfigMapper; import com.allinone.supply.service.IWorkflowConfigService; import java.util.List; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.stereotype.Service;
@Service public class WorkflowConfigServiceImpl implements IWorkflowConfigService { @Autowired private WorkflowConfigMapper mapper; @Override public List<WorkflowConfig> list(){requireAdmin();return mapper.selectAll();} @Override public int save(WorkflowConfig c){requireAdmin();if(c==null||c.getFlowType()==null||c.getFlowType().isBlank())throw new ServiceException("流程类型不能为空");WorkflowConfig old=mapper.selectLatest(c.getFlowType());c.setId(IdUtils.nextLongId());c.setVersion(old==null?1:old.getVersion()+1);return mapper.insert(c);} private void requireAdmin(){if(!SecurityUtils.isAdmin())throw new ServiceException("仅管理员可以配置审批流程");} }
